package com.portfolio.urlshortener.dto;
import jakarta.validation.constraints.*; import java.time.Instant;
public class UrlDtos {private UrlDtos(){} public record CreateUrlRequest(@NotBlank @Size(max=2048) String originalUrl,@Pattern(regexp="^[a-zA-Z0-9_-]{4,32}$",message="Alias must be 4-32 URL-safe characters") String customAlias,Instant expiresAt){} public record UpdateUrlRequest(@Size(max=2048) String originalUrl,Instant expiresAt,Boolean enabled,Boolean clearExpiration){} public record UrlResponse(Long id,String shortCode,String shortUrl,String originalUrl,boolean enabled,Instant expiresAt,Instant createdAt){} public record AnalyticsResponse(String shortCode,long totalClicks,long clicksLast30Days,long clicksThisMonth,java.util.List<DailyCount> dailyClicks,java.util.List<RecentClick> recentClicks){} public record DailyCount(String date,long clicks){} public record RecentClick(Instant clickedAt,String referrer,String deviceCategory,String browser){} public record DashboardResponse(long totalUrls,long totalClicks,java.util.List<UrlResponse> urls){} }
